let _ExcIPs_raw = '{ExcludedIPs}';
let _ExcIPs = iif(_ExcIPs_raw == '', dynamic([]),
    todynamic(strcat('["', replace_string(replace_string(_ExcIPs_raw, ' ', ''), ',', '","'), '"]')));
let _ExcCountries = dynamic([{ExcludedCountries}]);
let _AppSel = dynamic([{Apps}]);
let _IssSel = dynamic([{Issuers}]);
let ADFSSignInLogs = ADFSSignInLogs
    {WatchlistFilter}
    | extend IPAddress = tostring(IPAddress)
    | where _ExcIPs_raw == '' or isempty(IPAddress) or not(ipv4_is_in_any_range(IPAddress, _ExcIPs))
    | where array_length(_ExcCountries) == 0 or isempty(Location) or Location !in~ (_ExcCountries)
    | where array_length(_AppSel) == 0 or isempty(AppDisplayName) or AppDisplayName !in~ (_AppSel)
    | where array_length(_IssSel) == 0 or isempty(TokenIssuerName) or TokenIssuerName !in~ (_IssSel);
ADFSSignInLogs
| where TimeGenerated {TimeRange}
| summarize
    TotalSignIns = count(),
    SuccessfulSignIns = countif(ResultType == 0),
    FailedSignIns = countif(ResultType != 0),
    UniqueUsers = dcount(UserPrincipalName),
    UniqueIPs = dcount(IPAddress),
    UniqueLocations = dcount(Location),
    UniqueIssuers = dcount(TokenIssuerName)
| extend FailureRate = round(todouble(FailedSignIns) / TotalSignIns * 100, 2)
| project Metric = pack_array('Total Sign-Ins','Successful','Failed','Failure Rate %','Unique Users','Unique IPs','Unique Locations','Unique Issuers'),
          Value  = pack_array(TotalSignIns,SuccessfulSignIns,FailedSignIns,FailureRate,UniqueUsers,UniqueIPs,UniqueLocations,UniqueIssuers)
| mv-expand Metric to typeof(string), Value to typeof(string)

