let CurrentWeek = ADFSSignInLogs
| where TimeGenerated >= ago(7d)
| summarize CurrentTotal = count(), CurrentFailed = countif(ResultType != 0) by bin(TimeGenerated, 1d);
let PreviousWeek = ADFSSignInLogs
| where TimeGenerated between (ago(14d) .. ago(7d))
| summarize BaselineTotal = count(), BaselineFailed = countif(ResultType != 0);
let BaselineAvg = toscalar(PreviousWeek | project BaselineTotal) / 7.0;
let BaselineFailedAvg = toscalar(PreviousWeek | project BaselineFailed) / 7.0;
CurrentWeek
| extend TotalDeviation = round((todouble(CurrentTotal) - BaselineAvg) / BaselineAvg * 100, 2)
| extend FailedDeviation = round((todouble(CurrentFailed) - BaselineFailedAvg) / iif(BaselineFailedAvg == 0, 1.0, BaselineFailedAvg) * 100, 2)
| extend Indicator = case(
    TotalDeviation > 50, '🔴 High Increase',
    TotalDeviation > 20, '🟠 Moderate Increase',
    TotalDeviation < -50, '🔵 Significant Decrease',
    TotalDeviation < -20, '🟡 Moderate Decrease',
    '🟢 Normal')
| project Day = format_datetime(TimeGenerated, 'yyyy-MM-dd'), CurrentTotal, BaselineAvg = round(BaselineAvg, 0), TotalDeviation, Indicator, CurrentFailed, BaselineFailedAvg = round(BaselineFailedAvg, 0), FailedDeviation
| order by Day desc

