    | where Fails > toint('{FailureThreshold}') * 2 and IPs > 1 | count);
print Metric = pack_array('Extranet Lockouts','Password Spray IPs','Brute-Force Users','High-Risk Country Sign-ins'),
      Value  = pack_array(Lockouts, SprayIPs, BruteUsers, HRCountry)
| mv-expand Metric to typeof(string), Value to typeof(long)

